/**
 * Escapes the SQL `LIKE` wildcards (`%`, `_`) and the escape character itself
 * (`\`) so a query's free text is matched literally (ADR 0007 rule 1): every
 * character the user typed is looked for as typed, never as a wildcard.
 */
function likeContainsPattern(value: string): string {
  const escaped = value
    .replace(/\\/g, "\\\\")
    .replace(/%/g, "\\%")
    .replace(/_/g, "\\_");
  return `%${escaped}%`;
}

