254	  const at = content.toLowerCase().indexOf(query.toLowerCase());
255	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
256	
257	  const start = Math.max(0, at - SNIPPET_RADIUS);
258	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
259	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
260	    end < content.length ? "…" : ""
261	  }`;
262	}
